    elif hp <= 4 or no_water_days >= 2:
        if previous_bids:
            base_bid = max(previous_bids) + 2.0
        else:
            base_bid = DAILY_SALARY * 0.7
    else:
        if previous_bids:
            max_prev = max(previous_bids)
            if max_prev > DAILY_SALARY * 0.8:
